# Generated by build.py from recipe.yml for recipe smtp-send-mail-with-an-attachment. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '--mail-domain', 'example.com', '--mailbox', 'app@example.com:apppass', '--mailbox', 'ann@example.com:annpass', '--mailbox', 'bob@example.com:bobpass', 'smtp://127.0.0.1:8080/', 'imap://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS -u app@example.com:apppass --mail-from app@example.com --mail-rcpt ann@example.com -H "Subject: Nightly build report" -H "From: app@example.com" -H "To: ann@example.com" -F "=The nightly build report is attached." -F "=@report.csv;type=text/csv;encoder=base64" -o NUL -w "%{response_code}\n" smtp://127.0.0.1:8080/example.com && curl -sS --retry 10 --retry-all-errors --retry-delay 1 -u ann@example.com:annpass "imap://127.0.0.1:8081/INBOX;UID=1;SECTION=2" | tr -d "\r" | base64 -d | cmp - report.csv && echo part 2 is report.csv } finally { Stop-Process $server0 }
